function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var R=prng(66001);
var T0=Date.now();
var W=4,T=200,K=20,PF=0.02;
var state=[],ckpt=[];
for(var i=0;i<W;i++){state.push(0);ckpt.push(0);}
var lost=0,fails=0;
for(var t=1;t<=T;t++){
  for(var i=0;i<W;i++)state[i]++;
  if(t%K===0)for(var i=0;i<W;i++)ckpt[i]=state[i];
  for(var i=0;i<W;i++)if(R()<PF){lost+=state[i]-ckpt[i];state[i]=ckpt[i];fails++;}
}
console.log(JSON.stringify({id:"JAH-APX66-000001",ok:true,metrics:{workers:W,ticks:T,failures:fails,work_units_lost:lost,max_losable_per_failure:K-1,recovered_via_checkpoint:true},ms:Date.now()-T0}));

